bl_info = {
    "name": "3D Flowhub Scene Cleaner",
    "author": "3D Flowhub AI Team",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "View3D > Sidebar > 3D Flowhub",
    "description": "Cleans transforms, duplicate vertices, and loose geometry for imported 3D scenes.",
    "category": "Mesh",
};

import bpy

class FLOWHUB_OT_clean_scene(bpy.types.Operator):
    """Clean selected mesh objects in the scene"""
    bl_idname = "flowhub.clean_scene"
    bl_label = "Clean Scene Data"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        selected_objects = [obj for obj in context.selected_objects if obj.type == 'MESH']

        if not selected_objects:
            self.report({'WARNING'}, "No mesh objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            context.view_layer.objects.active = obj

            # Apply rotation and scale
            bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

            # Set origin to geometry center
            bpy.ops.object.origin_set(type='ORIGIN_GEOMETRY', center='BOUNDS')

            # Enter edit mode to clean mesh data
            bpy.ops.object.mode_set(mode='EDIT')
            bpy.ops.mesh.select_all(action='SELECT')

            # Remove duplicate vertices
            bpy.ops.mesh.remove_doubles(threshold=0.0001)

            # Delete loose vertices
            bpy.ops.mesh.delete_loose(use_face=False, use_edge=False)

            # Return to object mode
            bpy.ops.object.mode_set(mode='OBJECT')

        self.report({'INFO'}, f"Successfully cleaned {len(selected_objects)} objects.")
        return {'FINISHED'}

class FLOWHUB_PT_panel(bpy.types.Panel):
    bl_label = "3D Flowhub Cleaner"
    bl_idname = "FLOWHUB_PT_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "3D Flowhub"

    def draw(self, context):
        layout = self.layout
        layout.operator("flowhub.clean_scene", icon='TOOL_SETTINGS')

classes = (
    FLOWHUB_OT_clean_scene,
    FLOWHUB_PT_panel,
)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in classes:
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
